package com.barangayconnect.auth;
import com.barangayconnect.audit.*;import com.barangayconnect.user.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.data.domain.Sort;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.time.Instant;import java.util.*;
import static com.barangayconnect.auth.AuthDtos.*;
@Service public class AuthService {
 private final UserRepository users;private final LoginSessionRepository sessions;private final AuditLogRepository audit;private final PasswordEncoder encoder;private final JwtService jwt;
 public AuthService(UserRepository u,LoginSessionRepository s,AuditLogRepository a,PasswordEncoder e,JwtService j){users=u;sessions=s;audit=a;encoder=e;jwt=j;}
 @Transactional public AuthResponse register(RegisterRequest r,HttpServletRequest req){String email=r.email().trim().toLowerCase(Locale.ROOT),mobile=r.mobileNumber().trim();if(users.existsByEmailIgnoreCase(email))throw new ResponseStatusException(HttpStatus.CONFLICT,"An account with this email already exists.");if(users.existsByMobileNumber(mobile))throw new ResponseStatusException(HttpStatus.CONFLICT,"An account with this mobile number already exists.");UserAccount u=new UserAccount();u.setFullName(r.fullName().trim());u.setEmail(email);u.setMobileNumber(mobile);u.setAddress(r.address().trim());u.setPasswordHash(encoder.encode(r.password()));u.setRole(UserRole.RESIDENT);users.save(u);audit.save(new AuditLog(u.getId(),u.getEmail(),"REGISTER","USER_ACCOUNT",u.getId(),ip(req)));return session(u);}
 @Transactional public AuthResponse login(LoginRequest r,HttpServletRequest req){String id=r.identifier().trim();UserAccount u=users.findByEmailIgnoreCase(id).or(()->users.findByMobileNumber(id)).orElse(null);if(u==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email/mobile number or password.");if(!u.isActive())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This account has been deactivated. Contact the system administrator.");if(u.getLockedUntil()!=null&&u.getLockedUntil().isAfter(Instant.now()))throw new ResponseStatusException(HttpStatus.LOCKED,"Too many failed attempts. Try again after 15 minutes.");if(!encoder.matches(r.password(),u.getPasswordHash())){int n=u.getFailedLoginAttempts()+1;u.setFailedLoginAttempts(n);if(n>=5){u.setLockedUntil(Instant.now().plusSeconds(900));u.setFailedLoginAttempts(0);}users.save(u);audit.save(new AuditLog(u.getId(),u.getEmail(),"LOGIN_FAILED","USER_ACCOUNT",u.getId(),ip(req)));throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email/mobile number or password.");}u.setFailedLoginAttempts(0);u.setLockedUntil(null);users.save(u);audit.save(new AuditLog(u.getId(),u.getEmail(),"LOGIN","USER_ACCOUNT",u.getId(),ip(req)));return session(u);}
 @Transactional public void logout(String header,String email,HttpServletRequest req){if(header!=null&&header.startsWith("Bearer "))try{var c=jwt.parse(header.substring(7));sessions.findByJti(c.getId()).ifPresent(s->{s.setRevoked(true);sessions.save(s);});}catch(Exception ignored){}users.findByEmailIgnoreCase(email).ifPresent(u->audit.save(new AuditLog(u.getId(),u.getEmail(),"LOGOUT","USER_ACCOUNT",u.getId(),ip(req))));}
 @Transactional public UserResponse createOfficial(CreateOfficialRequest r,HttpServletRequest req){if(r.role()==UserRole.RESIDENT)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Use resident registration for resident accounts.");String email=r.email().trim().toLowerCase(Locale.ROOT);if(users.existsByEmailIgnoreCase(email)||users.existsByMobileNumber(r.mobileNumber()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email or mobile number is already registered.");UserAccount u=new UserAccount();u.setFullName(r.fullName().trim());u.setEmail(email);u.setMobileNumber(r.mobileNumber());u.setAddress(r.address().trim());u.setPasswordHash(encoder.encode(r.temporaryPassword()));u.setRole(r.role());users.save(u);audit.save(new AuditLog(null,"system","OFFICIAL_ACCOUNT_CREATED","USER_ACCOUNT",u.getId(),ip(req)));return dto(u);}
 @Transactional public void setActive(Long id,boolean active,String actor){UserAccount u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found."));u.setActive(active);users.save(u);audit.save(new AuditLog(null,actor,active?"ACCOUNT_ACTIVATED":"ACCOUNT_DEACTIVATED","USER_ACCOUNT",id,null));}
 @Transactional public UserResponse updateProfile(String email,String fullName,String address,String mobile,HttpServletRequest req){UserAccount u=users.findByEmailIgnoreCase(email).orElseThrow();if(mobile!=null&&!mobile.isBlank()&&!mobile.equals(u.getMobileNumber())&&users.existsByMobileNumber(mobile.trim()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Mobile number is already registered.");if(fullName!=null&&!fullName.isBlank())u.setFullName(fullName.trim());if(address!=null&&!address.isBlank())u.setAddress(address.trim());if(mobile!=null&&!mobile.isBlank())u.setMobileNumber(mobile.trim());users.save(u);audit.save(new AuditLog(u.getId(),u.getEmail(),"PROFILE_UPDATED","USER_ACCOUNT",u.getId(),ip(req)));return dto(u);}
 @Transactional public void changePassword(String email,String current,String next){UserAccount u=users.findByEmailIgnoreCase(email).orElseThrow();if(!encoder.matches(current,u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current password is incorrect.");if(next==null||next.length()<8||next.length()>72)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"New password must be at least 8 characters.");u.setPasswordHash(encoder.encode(next));users.save(u);audit.save(new AuditLog(u.getId(),u.getEmail(),"PASSWORD_CHANGED","USER_ACCOUNT",u.getId(),null));}
 public UserResponse current(String email){return users.findByEmailIgnoreCase(email).map(this::dto).orElseThrow();}public List<UserResponse> all(){return users.findAll().stream().map(this::dto).toList();}public List<AuditLog> logs(){return audit.findAll(Sort.by(Sort.Direction.DESC,"createdAt"));}
 private AuthResponse session(UserAccount u){String jti=jwt.newJti();Instant exp=Instant.now().plusSeconds(jwt.getExpirationSeconds());sessions.save(new LoginSession(u,jti,exp));return new AuthResponse(jwt.createToken(u,jti),"Bearer",jwt.getExpirationSeconds(),dto(u));}
 private UserResponse dto(UserAccount u){return new UserResponse(u.getId(),u.getFullName(),u.getEmail(),u.getMobileNumber(),u.getAddress(),u.getRole(),u.isActive());}private String ip(HttpServletRequest r){return r.getRemoteAddr();}
}